package io.joshuasalcedo.swaswa.ui.autoupdate;

import io.joshuasalcedo.swaswa.html.Node;
import io.joshuasalcedo.swaswa.html.PageScript;
import io.joshuasalcedo.swaswa.react.ReactElement;
import io.joshuasalcedo.swaswa.ui.Ui;
import java.util.List;
import java.util.function.Consumer;

/**
 * swaswa-ui's {@code Changelog} (changelog.tsx), a real React component, from Java: create it, set it, add it.
 * Generated by swaswa-react java-gen from its TypeScript props: do not edit.
 */
public final class UiChangelog extends ReactElement<UiChangelog> {

    /** A UiChangelog. */
    public UiChangelog() {
        super("Changelog", false);
    }

    /** {@code markdown}. The changelog's Markdown (a CHANGELOG.md). */
    public UiChangelog setMarkdown(String value) {
        return prop("markdown", value);
    }

    public String getMarkdown() {
        return getProp("markdown", String.class);
    }

    /** {@code since}. Only the versions after this one (What's new since the version last run). */
    public UiChangelog setSince(String value) {
        return prop("since", value);
    }

    public String getSince() {
        return getProp("since", String.class);
    }

    /** {@code only}. Only this version (an update's notes). */
    public UiChangelog setOnly(String value) {
        return prop("only", value);
    }

    public String getOnly() {
        return getProp("only", String.class);
    }

    /** {@code upTo}. Up to this version (no unreleased entries newer than the app). */
    public UiChangelog setUpTo(String value) {
        return prop("upTo", value);
    }

    public String getUpTo() {
        return getProp("upTo", String.class);
    }

    /** Told when it calls {@code onLink}, with what it calls it with. */
    public UiChangelog onLink(Consumer<String> listener) {
        return onEvent("onLink", e -> listener.accept(e.payload(String.class)));
    }

    /** {@code empty}: {@code node} (a component, or several in one), where the component draws it. */
    public UiChangelog setEmpty(Node node) {
        return slot("empty", node);
    }

    /** {@code empty}. */
    public UiChangelog setEmpty(String value) {
        return prop("empty", value);
    }

    public String getEmpty() {
        return getProp("empty", String.class);
    }

    @Override
    protected List<PageScript> libraries() {
        return List.of(Ui.bundle());
    }
}
